# اپ‌هایی که با شناسه‌ی پلتفرم‌محور ثبت شده‌اند ولی لوگوی مشترک دارند.
APP_LOGO_ALIAS = {
    'happ_ios': 'happ',
    'incy_ios': 'incy',
    'clashverge_mac': 'clashverge',
    'v2box_mac': 'v2box',
}


def logo_key(app_id):
    """شناسه‌ی لوگو برای یک اپ، یا None اگر لوگویی ثبت نشده باشد."""
    key = APP_LOGO_ALIAS.get(app_id, app_id)
    return key if key in APP_LOGOS else None
